INSERT INTO public.sanctuary_content (id, title, content_type, category, duration, difficulty, creator, origin, story_hook, used_by, sub_type, language, thumbnail_url, steps_count, tags, is_active, display_order, protocol_type, intensity_level, energy_direction, goal_tags, physio_targets, equipment, environment) VALUES
('rumination-exit-protocol','Exit the Overthinking Loop','micro-practice','pause',4,'beginner','Marcus Aurelius + Aaron Beck + Jeff Bezos','Stoic Philosophy + Cognitive Behavioral Therapy + Amazon Regret Minimization Framework','Every CEO has been there: 3am, cycling through the same decision for the 40th time. The Stoics called it ''disturbing ourselves''—they had a protocol for it. Jeff Bezos built a decision framework to escape it. Aaron Beck proved you can interrupt the thought loop. This combines all three.','CEOs, Founders, C-Suite Leaders, High-Performers under pressure','mindset','en','/assets/recalibrate/pause/rumination-exit-protocol.jpg',4,ARRAY['rumination','overthinking','decision','mental-loop','sleep'],true,0,'mindset','low','downshift',ARRAY['mental_clarity','emotional_regulation','decision_quality','grounding'],ARRAY['cortisol_reduce','prefrontal_activation','parasympathetic_activation'],ARRAY['none'],ARRAY['private','office','home']),
('failure-reframe-pivot','Turn Failure Into a Forward Move','micro-practice','pause',5,'intermediate','Thomas Edison + Ray Dalio + Viktor Frankl','Edison''s experimental method + Bridgewater Radical Transparency + Logotherapy (Frankl)','Edison called his 10,000 failures ''discoveries of what didn''t work.'' Dalio built an empire on radical transparency with failure. Frankl survived the Holocaust by finding meaning in suffering. The most durable leaders in history share one trait: they process failure faster than others.','Founders, CEOs, C-Suite Leaders after setbacks, failed launches, missed targets','mindset','en','/assets/recalibrate/pause/failure-reframe-pivot.jpg',4,ARRAY['failure','resilience','reframe','setback','growth'],true,0,'mindset','low','clarify',ARRAY['resilience','self_awareness','clarity','wisdom'],ARRAY['cortisol_reduce','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('political-navigation-clarity','Navigate Politics Without Being Pulled In','micro-practice','pause',4,'intermediate','Henry Kissinger + Sun Tzu + Robert Cialdini','Realpolitik diplomacy + The Art of War + Influence: The Psychology of Persuasion','Kissinger moved between superpowers not by force but by reading rooms others couldn''t. Sun Tzu mapped the terrain before moving. Great leaders don''t navigate office politics emotionally—they map it like terrain.','CEOs, C-Suite Leaders navigating board dynamics, stakeholder politics, internal power struggles','mindset','en','/assets/recalibrate/pause/political-navigation-clarity.jpg',4,ARRAY['politics','strategy','stakeholders','influence','leadership'],true,0,'mindset','low','clarify',ARRAY['clarity','strategic_thinking','composure','influence'],ARRAY['prefrontal_activation','cortisol_reduce'],ARRAY['none'],ARRAY['private','office','home']),
('pre-board-mastery-frame','Own the Room Before You Enter','micro-practice','presence',3,'beginner','Amy Cuddy + Tony Schwartz + Marcus Aurelius','Presence (Cuddy, Harvard) + The Power of Full Engagement + Meditations (Aurelius)','Before every speech, Demosthenes prepared alone. Before every conquest, Alexander visualized. Before every board meeting, the most effective leaders in history ran a version of this: enter the room already inside your best self.','CEOs, C-Suite Leaders before board meetings, investor presentations, major keynotes','mindset','en','/assets/recalibrate/presence/pre-board-mastery-frame.jpg',4,ARRAY['performance','presence','leadership','board','confidence'],true,0,'mindset','low','clarify',ARRAY['confidence','composure','focus','presence'],ARRAY['cortisol_reduce','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('stakeholder-listening-presence','Full Presence in a Conversation That Matters','micro-practice','presence',2,'beginner','Carl Rogers + Stephen Covey + Taoism','Person-centered therapy (Rogers) + The 7 Habits of Highly Effective People + Tao Te Ching','When Nelson Mandela walked into a room, people said he made you feel like you were the only person in the world. It wasn''t technique—it was a choice he made about where to put his attention. Carl Rogers showed that being truly heard reduces defensiveness more than any argument.','CEOs, C-Suite Leaders before or during 1:1s, high-stakes conversations, meetings where trust matters','mindset','en','/assets/recalibrate/presence/stakeholder-listening-presence.jpg',3,ARRAY['listening','presence','leadership','relationship','communication'],true,0,'mindset','low','clarify',ARRAY['focus','composure','communication','presence'],ARRAY['cortisol_reduce','coherence'],ARRAY['none'],ARRAY['private','office','home']),
('vision-reconnect-protocol','Reconnect to Why This Matters','micro-practice','presence',4,'beginner','Steve Jobs + Viktor Frankl + Jeff Bezos','Jobs''s ''connecting the dots'' + Logotherapy + Bezos''s ''working backwards''','When Jobs was building Apple''s comeback, he would regularly step back and ask: ''Is this what we''re for?'' Not the quarterly metrics—the fundamental question of purpose. Bezos asks teams to write the press release for the product before building it.','CEOs, Founders, C-Suite Leaders who''ve lost connection to the larger purpose driving the work','mindset','en','/assets/recalibrate/presence/vision-reconnect-protocol.jpg',4,ARRAY['vision','purpose','leadership','motivation','direction'],true,0,'mindset','low','clarify',ARRAY['motivation','clarity','resilience','wisdom'],ARRAY['dopamine_regulation','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('identity-shift-prime','Step Into Your Best Self','micro-practice','power-up',3,'beginner','Amy Cuddy + William James + Cognitive Behavioral Therapy','Presence (Cuddy) + Principles of Psychology (James) + Identity-based behavior change','William James discovered it in 1890: ''Act as if what you do makes a difference. It does.'' Cuddy''s research formalized it: brief physical and mental ''power states'' change hormone levels and performance before you begin. The most effective CEOs don''t wait to feel confident—they adopt the identity and the feeling follows.','CEOs, C-Suite Leaders before high-performance moments, when confidence is needed before it''s felt','mindset','en','/assets/recalibrate/power-up/identity-shift-prime.jpg',4,ARRAY['identity','confidence','performance','prime','energy'],true,0,'mindset','medium','upshift',ARRAY['confidence','composure','energy','performance'],ARRAY['cortisol_reduce','hrv_increase'],ARRAY['none'],ARRAY['private','office','home']),
('competitive-hunger-awaken','Reignite Your Competitive Edge','micro-practice','power-up',3,'intermediate','Michael Jordan + Kobe Bryant + Stoic Competition Philosophy','Jordan''s competitive philosophy + Mamba Mentality (Kobe) + Stoic fueling of excellence','Kobe Bryant woke at 4am not because he had to—because he genuinely loved being first to start. Jordan competed so hard because losing at anything was unacceptable. The greatest competitors didn''t manufacture motivation. They remembered what they were playing for.','CEOs, Founders, C-Suite Leaders who need to reignite competitive drive or face a formidable competitor','mindset','en','/assets/recalibrate/power-up/competitive-hunger-awaken.jpg',4,ARRAY['competition','drive','motivation','hunger','performance'],true,0,'mindset','high','upshift',ARRAY['motivation','energy','performance','resilience'],ARRAY['dopamine_regulation','hrv_increase'],ARRAY['none'],ARRAY['private','office','home']),
('possibility-mindset-open','Break Through Your Ceiling','micro-practice','power-up',4,'beginner','Carol Dweck + Abraham Maslow + Elon Musk','Growth Mindset (Dweck) + Hierarchy of Needs / Peak Experiences + First Principles Thinking (Musk)','Dweck''s research is one of the most replicated in psychology: people who believe abilities can be developed achieve dramatically more than those who believe they''re fixed. Musk refuses to accept industry constraints as reality. Maslow described ''peak experiences''—moments of expanded possibility.','CEOs, Founders, C-Suite Leaders who need to break through self-imposed ceilings or think bigger','mindset','en','/assets/recalibrate/power-up/possibility-mindset-open.jpg',4,ARRAY['possibility','growth-mindset','expansion','ambition','mindset'],true,0,'mindset','medium','upshift',ARRAY['motivation','creativity','confidence','strategic_thinking'],ARRAY['dopamine_regulation','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home'])
INSERT INTO public.sanctuary_content_metadata (id, content_id, structured_tags, completion_quote, intro_summary, essence, parallel, cue, why_this_works, mastery_category, horizon, meta_skill, is_foundational, moment, state_signal, duration_band) VALUES
(gen_random_uuid(),'rumination-exit-protocol','{"pillar": "pause", "intensityLevel": "low", "energyDirection": "downshift", "contextTags": ["Cycling on a decision", " can''t let go", " replaying a conversation", " overthinking at the expense of sleep or presence"], "goalTags": ["mental_clarity", "emotional_regulation", "decision_quality", "grounding"], "physioTarget": ["cortisol_reduce", "prefrontal_activation", "parasympathetic_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','The loop is broken. You chose to exit.','Cycling on a decision you can''t let go of. Break the loop deliberately.','Rumination is not thinking—it''s the rehearsal of suffering. Exit the loop deliberately.','Cognitive defusion (ACT); Negative visualization (Stoic); 10/10/10 rule (Suzy Welch); Regret Minimization (Bezos)','I''ve gathered what I need. I release the rest.','Rumination activates the brain''s default mode network without resolution. Writing thoughts out externalizes them; time-perspective shifting reduces anxiety; a closing ritual signals completion to the nervous system.','{"primary": "meta-clarity", "secondary": ["pause", "meta-recalibration"]}','{immediate,tactical}','{meta-clarity,meta-recalibration}',false,'{moment-evening-close,moment-crisis}','{signal-depleted,signal-clarity-low}','short'),
(gen_random_uuid(),'failure-reframe-pivot','{"pillar": "pause", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["After a significant failure", " loss", " missed milestone", " public setback"], "goalTags": ["resilience", "self_awareness", "clarity", "wisdom"], "physioTarget": ["cortisol_reduce", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','The failure taught you something no success could. You''ve learned.','After a setback, loss, or missed target. Extract the learning before it hardens into shame.','The failure is data. You are the architect. Architects study the collapse to build better.','Growth mindset (Dweck); Antifragility (Taleb); Post-mortem analysis; Amor fati (Nietzsche)','This happened. I choose what it means.','Failure triggers shame and avoidance which close down learning. Meaning-making (Frankl) and deliberate reframing (Dweck/CBT) switch the brain from threat to curiosity mode. Extracting lessons within 24 hours significantly increases probability of success in subsequent attempts.','{"primary": "meta-recalibration", "secondary": ["pause", "meta-renewal"]}','{immediate,tactical}','{meta-recalibration,meta-renewal}',false,'{moment-post-meeting,moment-evening-close}','{signal-confidence-low,signal-depleted}','short'),
(gen_random_uuid(),'political-navigation-clarity','{"pillar": "pause", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["Sensing political undercurrents", " navigating a complex stakeholder landscape", " before a politically charged meeting with hidden agendas"], "goalTags": ["clarity", "strategic_thinking", "composure", "influence"], "physioTarget": ["prefrontal_activation", "cortisol_reduce"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You see the board. You know your move.','When the political landscape is shifting. Map the interests before you make a move.','You cannot navigate terrain you haven''t mapped. See the board, not just the pieces.','Systems thinking; stakeholder mapping; chess vs checkers; Machiavellian intelligence','I see clearly who wants what. I move with strategy, not reaction.','Organizational politics trigger an emotional threat response which narrows thinking. This protocol deliberately activates strategic cognition by mapping interests and motivations before acting—converting emotional reaction to tactical intelligence.','{"primary": "meta-clarity", "secondary": ["pause"]}','{tactical,strategic}','{meta-clarity}',false,'{moment-pre-jit,moment-post-meeting}','{signal-clarity-low,signal-tense}','short'),
(gen_random_uuid(),'pre-board-mastery-frame','{"pillar": "flow", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["About to walk into a high-stakes room \u2014 board meeting", " investor presentation", " all-hands", " performance review"], "goalTags": ["confidence", "composure", "focus", "presence"], "physioTarget": ["cortisol_reduce", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You walked in as your best self. That is already leadership.','Before a board meeting or high-stakes room. Walk in as the most grounded person there.','You don''t find your best self in the room. You bring it in.','Pre-performance ritual (sport psychology); Mental rehearsal (Olympians); Power posing (Cuddy); Visualization (Mandela)','I have done the work. I am ready. This is mine.','Mental rehearsal activates the same neural pathways as physical performance. Pre-performance ritual reduces cortisol and increases testosterone. Entering a room with conscious ownership of your state is the single greatest predictor of perceived leadership presence.','{"primary": "meta-clarity", "secondary": ["presence"]}','{immediate}','{meta-clarity}',false,'{moment-pre-jit}','{signal-confidence-low,signal-clarity-low}','micro'),
(gen_random_uuid(),'stakeholder-listening-presence','{"pillar": "flow", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["About to enter a conversation that matters \u2014 with a key report", " board member", " investor", " or partner who needs to feel genuinely heard"], "goalTags": ["focus", "composure", "communication", "presence"], "physioTarget": ["cortisol_reduce", "coherence"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You were fully present. That is the rarest gift a leader can give.','Before a key conversation. Stop performing listening — actually be there.','You cannot lead people you haven''t heard. Full presence is not passive—it''s the most active thing you can do.','Active listening (Rogers); Presence (Buber''s I-Thou); Empathic accuracy (interpersonal neurobiology); Deep listening (Scharmer)','I am here. Fully. Only here.','When people feel genuinely heard, their nervous systems downregulate—defensiveness drops, creativity increases, trust accumulates. Leaders who practice full presence are perceived as more influential despite saying less.','{"primary": "meta-clarity", "secondary": ["presence"]}','{immediate}','{meta-clarity}',false,'{moment-pre-jit}','{signal-tense,signal-clarity-low}','micro'),
(gen_random_uuid(),'vision-reconnect-protocol','{"pillar": "flow", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["Lost in the operational detail", " motivation dipping", " team losing direction", " questioning whether it matters"], "goalTags": ["motivation", "clarity", "resilience", "wisdom"], "physioTarget": ["dopamine_regulation", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You remembered the why. Now the how becomes possible.','Lost in operational detail. Return to the vision driving the work.','The fire is always there. Sometimes you''ve just been too close to the smoke.','Simon Sinek''s Why; Purpose-driven leadership; North Star principle; Transcendent purpose (research: Damon)','I remember why. That is enough.','Purpose activates intrinsic motivation—the most durable form of drive. Reconnecting to vision reduces anxiety, restores decision-making clarity, and increases resilience. Setbacks become obstacles, not ends.','{"primary": "meta-clarity", "secondary": ["presence"]}','{strategic,tactical}','{meta-clarity}',false,'{moment-evening-close,moment-post-meeting}','{signal-depleted,signal-clarity-low}','short'),
(gen_random_uuid(),'identity-shift-prime','{"pillar": "renewal", "intensityLevel": "medium", "energyDirection": "upshift", "contextTags": ["Need to show up at your best but not currently feeling it \u2014 pre-keynote", " pre-negotiation", " after a setback"], "goalTags": ["confidence", "composure", "energy", "performance"], "physioTarget": ["cortisol_reduce", "hrv_increase"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You didn''t wait to feel it. You became it. That is mastery.','Before a high-stakes performance moment. Act from the identity you need — feeling follows action.','Don''t wait to feel ready. Act from the identity of who you are becoming—and become it.','Act as if (Adlerian psychology); Behavioral activation (CBT); Future-self psychology (Hershfield); Role adoption','I am already who I need to be.','Identity-based behavior change is more durable than motivation-based change. Adopting a specific self-concept causes decision-making to align with that identity automatically. Cuddy''s research confirms 2 minutes of power posture changes cortisol-testosterone ratios measurably.','{"primary": "meta-renewal", "secondary": ["power-up"]}','{immediate}','{meta-renewal}',false,'{moment-pre-jit}','{signal-confidence-low,signal-low-energy}','micro'),
(gen_random_uuid(),'competitive-hunger-awaken','{"pillar": "renewal", "intensityLevel": "high", "energyDirection": "upshift", "contextTags": ["Losing competitive edge", " feeling complacent", " up against a serious competitor", " need to raise the game"], "goalTags": ["motivation", "energy", "performance", "resilience"], "physioTarget": ["dopamine_regulation", "hrv_increase"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','The fire is lit. Now direct it precisely.','When hunger has faded or complacency crept in. Remember what you''re playing for.','Complacency is a choice. So is hunger. Choose.','Competitive fire (flow research—optimal challenge); Constructive anger; Warrior''s mindset (military); Self-determination theory','I love this game. I play to win.','Competitive drive that is intrinsic (love of the game) rather than extrinsic (fear of failure) is significantly more sustainable and produces higher performance. This protocol reconnects to intrinsic motivation and converts healthy competitive awareness into targeted energy.','{"primary": "meta-renewal", "secondary": ["power-up"]}','{immediate,tactical}','{meta-renewal}',false,'{moment-pre-jit,moment-post-meeting}','{signal-low-energy,signal-depleted}','micro'),
(gen_random_uuid(),'possibility-mindset-open','{"pillar": "renewal", "intensityLevel": "medium", "energyDirection": "upshift", "contextTags": ["Thinking too small", " accepting constraints that shouldn''t be accepted", " self-imposed ceiling on what''s possible"], "goalTags": ["motivation", "creativity", "confidence", "strategic_thinking"], "physioTarget": ["dopamine_regulation", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','The horizon expanded. What you do with it is yours to decide.','Thinking too small or accepting limits that aren''t real. Expand what you believe is achievable.','The ceiling you see is almost always a belief, not a fact.','Growth mindset (Dweck); Abundance mindset (Covey); Moonshot thinking (Google X); Possibility thinking','What would I attempt if I knew I couldn''t fail?','Fixed mindset beliefs trigger threat-avoidance, which narrows thinking and reduces creative problem-solving. Growth mindset beliefs activate the approach system, widening the range of options the brain generates.','{"primary": "meta-renewal", "secondary": ["power-up"]}','{tactical,strategic}','{meta-renewal}',false,'{moment-pre-jit,moment-post-meeting}','{signal-confidence-low,signal-depleted}','short');
INSERT INTO public.sanctuary_content_steps (id, content_id, step_order, title, instruction, duration, breathing_pattern, wisdom_note) VALUES
(gen_random_uuid(),'rumination-exit-protocol',1,'Empty the Loop','Take a blank page or open note. Set a timer for 90 seconds. Write every thought circling in your head about this topic without editing. Not sentences—fragments are fine. Get it out of your head and onto the page.',90,NULL,'The mind is a terrible storage device for unresolved problems. Paper is better.'),
(gen_random_uuid(),'rumination-exit-protocol',2,'Apply the Bezos Test','Ask yourself: ''In 10 years, will this decision matter?'' Bezos''s rule: most decisions are reversible doors—you walk through and can return. Identify which kind this is. Only irreversible decisions need this level of energy.',60,NULL,'Most of what we agonize over is a two-way door. You can walk back through.'),
(gen_random_uuid(),'rumination-exit-protocol',3,'Identify What You Can''t Control','Draw a line. Left side: what is IN my control. Right side: what is NOT. Everything on the right? Intentionally let go of it. The Stoics called this the ''dichotomy of control.''',45,NULL,'You suffer more in imagination than in reality. — Seneca'),
(gen_random_uuid(),'rumination-exit-protocol',4,'Make One Small Decision','Don''t try to solve everything. Just name the next single action. ''The one thing I''ll do tomorrow on this is ___.'' The act of deciding—even a tiny decision—breaks the loop.',45,NULL,'Done is better than perfect—but starting is better than both.'),
(gen_random_uuid(),'failure-reframe-pivot',1,'Name What Happened (Facts Only)','Write one sentence: what factually happened? No interpretation. No story. Just the observable facts. ''The product launch did not hit target.'' Strip the narrative.',60,NULL,'You cannot process what you haven''t accurately named. Start with facts.'),
(gen_random_uuid(),'failure-reframe-pivot',2,'Separate Outcome from Identity','Ask: ''Did I fail, or did this attempt fail?'' You are not the result. Complete this sentence: ''I made a decision to ___. Given what I knew then, it was ___.''',60,NULL,'You are the explorer, not the map. The territory revealed something new.'),
(gen_random_uuid(),'failure-reframe-pivot',3,'Extract the Data','What three things did this failure reveal? What assumptions proved wrong? What would an Edison or a Dalio ask right now? Label each insight: ''What this showed me is ___.''',90,NULL,'Edison had 10,000 data points before the lightbulb. How many do you have?'),
(gen_random_uuid(),'failure-reframe-pivot',4,'Choose the Meaning','Viktor Frankl''s central insight: we cannot control what happens, only the meaning we assign. In one sentence: what meaning do you CHOOSE to give this failure? Make it generative, not punishing.',60,NULL,'Between stimulus and response there is a space. In that space is our freedom. — Frankl'),
(gen_random_uuid(),'political-navigation-clarity',1,'Map the Players','List the key people involved. Next to each, write ONE thing: what do they most want from this situation? Not what they say they want—what they actually want. Power, credit, safety, influence?',60,NULL,'Know your enemy and know yourself—in a hundred battles you will never be defeated. — Sun Tzu'),
(gen_random_uuid(),'political-navigation-clarity',2,'Identify the Real Constraint','What is the one thing that, if it shifted, would change everything? Usually it''s one relationship, one fear, or one misaligned incentive. Diplomats call this the ''blocking faction''.',60,NULL,'Kissinger always found the one door. He didn''t push on walls.'),
(gen_random_uuid(),'political-navigation-clarity',3,'Find the Common Ground','Where do YOUR interests and THEIR interests overlap? Name it specifically. This becomes your leverage—not power over them, but alignment with them.',45,NULL,'People move toward those who understand them, not those who overpower them. — Cialdini'),
(gen_random_uuid(),'political-navigation-clarity',4,'Choose Your First Move','What is the one action, conversation, or signal that creates forward momentum without triggering resistance? Small moves change large landscapes.',45,NULL,'The highest form of leadership is to win without fighting. — Tao Te Ching'),
(gen_random_uuid(),'pre-board-mastery-frame',1,'Recall Your Evidence','In your mind, name three times you performed brilliantly under pressure. Specific moments. Feel them—don''t just remember them intellectually. This primes your neural system with the state of mastery.',45,NULL,'Confidence is earned through memory, not manufactured by affirmation.'),
(gen_random_uuid(),'pre-board-mastery-frame',2,'Visualize Your Best Version','Close your eyes. See yourself walking into that room. See your posture, your eye contact, your calm. Hear yourself speaking with authority and warmth. Feel the difference between performing and being. Hold it for 45 seconds.',45,NULL,'The mind cannot distinguish between a vividly imagined event and a real one. Choose what it rehearses.'),
(gen_random_uuid(),'pre-board-mastery-frame',3,'Set Your Anchor','Choose one physical anchor—a breath, a hand position. Take a slow breath, connect to your best-self state, and press the anchor. You can activate this state instantly in the room by repeating the anchor.',45,'4 in, 6 out','Elite performers don''t hope to feel ready. They know how to create the state on demand.'),
(gen_random_uuid(),'pre-board-mastery-frame',4,'Walk In','Enter the room as if you already belong there—because you do. Before you say a word, be still for two full seconds. Stillness signals authority. The room will adjust to your state.',30,NULL,'The most powerful person in any room is the calmest one.'),
(gen_random_uuid(),'stakeholder-listening-presence',1,'Clear Your Internal Screen','Before this conversation: notice what''s running on your internal screen. Your next meeting. The email you didn''t answer. Acknowledge each and consciously set it aside. Say internally: ''That is there. I''ll return to it. Right now: this person.''',45,NULL,'You cannot give what you haven''t first chosen to give. Choose presence.'),
(gen_random_uuid(),'stakeholder-listening-presence',2,'Set Your Listening Intention','Ask yourself: ''What does this person most need me to understand from this conversation?'' Not what you plan to say—what do they need to have heard? This shifts you from evaluation mode to understanding mode.',30,NULL,'Seek first to understand. — Covey (from Rogers'' unconditional positive regard)'),
(gen_random_uuid(),'stakeholder-listening-presence',3,'Listen to the Gap','In the conversation: listen not just to words but to what''s underneath them. What are they not saying directly? Reflect back: ''It sounds like the real concern here is ___.''',30,NULL,'The most important things are never said directly. Listen for what''s underneath.'),
(gen_random_uuid(),'vision-reconnect-protocol',1,'Step Back to the Origin','In one sentence, write: ''The reason I started this—or took this role—was ___.'' Don''t write the polished version. Write the real one. What did you believe was possible?',60,NULL,'Start with why. — Jobs/Sinek. The why is always true even when the what is hard.'),
(gen_random_uuid(),'vision-reconnect-protocol',2,'Name the Dent','Jobs asked: ''How do we put a dent in the universe?'' What is the dent YOUR work is making? Not the revenue—the actual difference. Name it specifically.',60,NULL,'A leader without a vision is a manager. The difference is the dent.'),
(gen_random_uuid(),'vision-reconnect-protocol',3,'Write the Future Press Release','What does success look like in 3 years, written as a news story? Bezos called this ''working backwards.'' One paragraph. This converts abstract vision into concrete reality in the brain.',60,NULL,'The future is already written in your choices. Which story are you choosing?'),
(gen_random_uuid(),'vision-reconnect-protocol',4,'Choose One Thing Today','What is one action today that is a direct expression of that vision? Not the operationally urgent thing—the strategically meaningful thing.',30,NULL,'Vision without action is a daydream. Action without vision is a nightmare. — Japanese proverb'),
(gen_random_uuid(),'identity-shift-prime',1,'Name Your Best Self','Describe in one sentence the version of yourself at your absolute best: ''At my best, I am ___.'' Be specific. ''Decisive, calm under pressure, and genuinely curious'' is better than ''a good leader.''',45,NULL,'You are not trying to become someone new. You are remembering someone you already are.'),
(gen_random_uuid(),'identity-shift-prime',2,'Adopt the Posture','Stand tall. Shoulders back and down. Feet shoulder-width. Take up space. Cuddy''s research: open posture for 2 minutes measurably shifts cortisol down and testosterone up.',60,NULL,'The body leads and the mind follows. Posture is a signal to yourself.'),
(gen_random_uuid(),'identity-shift-prime',3,'Speak It Into Existence','Say aloud: ''I am ___'' using the identity you named in step 1. Three times. Not affirmation—declaration. The difference is the feeling of ownership behind it.',45,NULL,'The words ''I am'' are the most powerful creative force you possess. Use them precisely.'),
(gen_random_uuid(),'identity-shift-prime',4,'Begin From That Identity','Whatever comes next—walk into it as that person. Don''t wait for the feeling to confirm the identity. The feeling follows the action.',30,NULL,'You don''t have to feel it first. Act it first. Then feel it.'),
(gen_random_uuid(),'competitive-hunger-awaken',1,'Name the Competition','Who or what are you competing with? Be specific—not abstract. Name the competitor, the challenge, the position you want. Healthy competition requires knowing what you''re running toward.',45,NULL,'You cannot compete with a ghost. Name what you''re actually playing for.'),
(gen_random_uuid(),'competitive-hunger-awaken',2,'Remember Your Reason','Why does winning here matter? Not to the company—to YOU. What would it prove? What would it build? This is Kobe at 4am—not obligation, but love of the game.',45,NULL,'Obligation fatigues. Love of the game sustains.'),
(gen_random_uuid(),'competitive-hunger-awaken',3,'Feel the Fire','Close your eyes. Imagine the moment of effort—when you''re fully in it, giving everything. Feel your body''s response. Let that energy through. You don''t manufacture competitive fire—you remember it. It''s already there.',45,NULL,'Fire doesn''t need to be created. It needs to be uncaged.'),
(gen_random_uuid(),'competitive-hunger-awaken',4,'Channel It Precisely','Take that energy and direct it toward one specific action in the next hour. Not general effort—one precise high-leverage action. Great competitors burn hot and focus, not burn hot and scatter.',30,NULL,'Undirected fire burns everything. Directed fire wins everything.'),
(gen_random_uuid(),'possibility-mindset-open',1,'Name the Ceiling','What are you currently treating as an immovable constraint? Write it: ''We can''t ___ because ___.'' Now ask: ''Is this a physical law or a belief?'' Most ceilings are beliefs wearing the clothes of facts.',60,NULL,'The limits you accept become the limits you live within.'),
(gen_random_uuid(),'possibility-mindset-open',2,'The 10x Question','Ask: ''What would we do if we had 10 times the ambition on this?'' Don''t answer it practically—just open the horizon. Musk''s rule: 10x thinking creates genuinely different solutions than 10% thinking.',60,NULL,'10x thinking is categorical, not incremental. Different scale, different strategy.'),
(gen_random_uuid(),'possibility-mindset-open',3,'Find One Person Who Did It','Name someone who achieved something you believe is impossible in your context. How did they see through their version of your ceiling? Dweck: exposure to others who achieved the ''impossible'' expands perceived possibility.',60,NULL,'Impossible is what was achieved by people who refused the consensus.'),
(gen_random_uuid(),'possibility-mindset-open',4,'Name Your Expanded Move','With the horizon expanded: what''s one action you would take that you currently aren''t? Not theoretical—practical. Write it. Do it.',30,NULL,'Possibility is a practice, not a feeling. Act from the expanded version.');
